package org.eclipse.myplugin;
import org.eclipse.jface.action.MenuManager;
import org.eclipse.ui.console.TextConsoleViewer;
import org.eclipse.ui.internal.console.FollowHyperlinkAction;

public class MyConsoleMenu {
    private TextConsoleViewer viewer;

    public MyConsoleMenu(TextConsoleViewer viewer) {
        this.viewer = viewer;
    }

    public void createMenu(MenuManager menuManager) {
        menuManager.add(new FollowHyperlinkAction(viewer));
    }
}

